#!/bin/sh
set -eu
python3 - <<'GUEST'
import base64,pathlib,subprocess,time,json
assert json.loads(pathlib.Path('/var/log/ideck-steam-install/result.json').read_text())['status']=='installed_private_client_not_launched'
r=subprocess.run(['dpkg','--audit'],capture_output=True)
assert r.returncode==0 and r.stdout==b'' and r.stderr==b''
out=pathlib.Path('/tmp/ideck-launch1');out.mkdir(exist_ok=False)
pathlib.Path('/tmp/observe-first.py').write_bytes(base64.b64decode(''))
with (out/'launcher.log').open('xb') as f:
 p=subprocess.Popen(['python3','/opt/ideck-steam/namespace-check.py','launch','desktop'],stdin=subprocess.DEVNULL,stdout=f,stderr=subprocess.STDOUT,start_new_session=True)
(out/'launcher.pid').write_text(str(p.pid))
with (out/'monitor.log').open('xb') as f:
 m=subprocess.Popen(['python3','/tmp/observe-first.py'],stdin=subprocess.DEVNULL,stdout=f,stderr=subprocess.STDOUT,start_new_session=True)
(out/'monitor.pid').write_text(str(m.pid))
print('FRESH_LAUNCH_PIDS',p.pid,m.pid,flush=True)
time.sleep(30)
print('FRESH_LAUNCHER_TAIL='+ (out/'launcher.log').read_text(errors='replace')[-5000:])
r=pathlib.Path('/tmp/ideck-first-attempt/result.json')
if r.exists():print('FRESH_FIRST_ATTEMPT_RESULT='+r.read_text())
GUEST
xset q
xwininfo -root -tree
